import re, sys

M = 65536
regs = {'a':0,'b':0,'c':0,'d':0}

# parse
ins = []
with open('/tmp/<path>') as f:
    for line in f:
        line = line.split(';',1)[0].strip()
        if not line:
            continue
        parts = line.split()
        ins.append(parts)

def val(tok):
    if tok in regs:
        return regs[tok]
    return int(tok)

def is_reg(tok):
    return tok in regs

def wrap(v):
    return v % M

ip = 0
count = 0
out = []
trace = []
steps = 0
while 0 <= ip < len(ins):
    steps += 1
    if steps > 10_000_000:
        print("too many"); break
    parts = ins[ip]
    op = parts[0]
    count += 1
    if op == 'set':
        r, x = parts[1], parts[2]
        regs[r] = wrap(val(x))
    elif op == 'add':
        r, x = parts[1], parts[2]
        regs[r] = wrap(regs[r] + val(x))
    elif op == 'mul':
        r, x = parts[1], parts[2]
        regs[r] = wrap(regs[r] * val(x))
    elif op == 'mod':
        r, x = parts[1], parts[2]
        xv = val(x)
        if xv > 0:
            regs[r] = regs[r] % xv
    elif op == 'dec':
        r = parts[1]
        if regs[r] > 0:
            regs[r] -= 1
    elif op == 'jnz':
        x, k = parts[1], parts[2]
        if val(x) != 0:
            ip = ip + val(k)
            continue
    elif op == 'skp':
        x, y = parts[1], parts[2]
        if val(x) < val(y):
            ip += 2
            continue
    elif op == 'out':
        x = parts[1]
        out.append(val(x))
        trace.append((ip, val(x), dict(regs)))
    else:
        raise Exception("bad op " + op)
    ip += 1

print("outputs:", out)
print("sum:", sum(out))
print("count:", count)
print("num outputs:", len(out))
