import sys

M = 65536
R = [0,0,0,0]  # a b c d
IDX = {'a':0,'b':1,'c':2,'d':3}

def parse(path):
    prog=[]
    for raw in open(path):
        s=raw.split(';',1)[0].strip()
        if s:
            prog.append(s.split())
    return prog

def get(tok):
    if tok in IDX: return R[IDX[tok]]
    return int(tok)

def run(path):
    P=parse(path)
    n=len(P)
    pc=0; cnt=0; outs=[]; skip=False; iters=0
    while 0 <= pc < n:
        if skip:
            skip=False
            pc+=1
            continue
        op=P[pc]; cnt+=1
        if op[0]=='set': R[IDX[op[1]]]=get(op[2])%M
        elif op[0]=='add': R[IDX[op[1]]]=(R[IDX[op[1]]]+get(op[2]))%M
        elif op[0]=='mul': R[IDX[op[1]]]=(R[IDX[op[1]]]*get(op[2]))%M
        elif op[0]=='mod':
            x=get(op[2])
            if x>0: R[IDX[op[1]]]%=x
        elif op[0]=='dec':
            if R[IDX[op[1]]]>0: R[IDX[op[1]]]-=1
        elif op[0]=='jnz':
            if get(op[1])!=0:
                pc = pc + get(op[2])
                iters+=1
                continue
        elif op[0]=='skp':
            if get(op[1]) < get(op[2]):
                skip=True
        elif op[0]=='out':
            outs.append(get(op[1]))
        else: raise ValueError(op)
        pc+=1
    return outs,cnt,R[:]

outs,cnt,R = run('/tmp/<path>')
print("sum",sum(outs),"count",cnt,"outputs",len(outs),"final regs",R)
print("last 6",outs[-6:])
